-- Seed data for the app_data schema (kanvy v7), analogous to server/db.json
-- as produced by server/generate-db.ts (the design-review fixture: one
-- showcase board per topic, linked from the home board).
--
-- Generated from the generator's output, not hand-written. Notes:
--   * App ids (nanoid-style strings) aren't uuids; each is mapped to
--     md5('<app id>')::uuid, and the app id is kept as a comment above its
--     row, so e.g. the home board is md5('h0me0b0ard00')::uuid.
--   * Timestamps are relative to now(), mirroring the generator's
--     relative-to-generation-time ages, so recency mode shows its full
--     spread whenever this is loaded.
--   * Absent optional fields (card_type/size/pattern/image_id/link_*/
--     board_ref/content) load as null.
--
-- Re-runnable: it truncates all app_data tables first.

begin;

truncate app_data.edges, app_data.nodes, app_data.images, app_data.boards;

